parameters.functionCode:
const body = $input.first().json;

// Required
if (!body.prompt || typeof body.prompt !== 'string' || body.prompt.trim().length < 5) {
  throw new Error('Missing or invalid prompt. Minimum 5 characters.');
}

// Sanitize: strip any shell-special chars from prompt to prevent injection
const safePrompt = body.prompt.replace(/[`$();|&<>\\]/g, ' ').trim();

// Validate aspect ratio
const validRatios = ['1:1', '16:9', '9:16', '4:3', '3:4'];
const ratio = validRatios.includes(body.aspect_ratio) ? body.aspect_ratio : '16:9';

// Validate count
const count = Math.min(Math.max(parseInt(body.count || 1, 10), 1), 4);

return [{ json: { prompt: safePrompt, aspect_ratio: ratio, count } }];

const raw = $input.first().json;
const stdout = raw.stdout || '';
const stderr = raw.stderr || '';

if (raw.exitCode !== 0) {
  throw new Error('Image generation failed: ' + stderr);
}

// Parse the JSON output from the script
let result;
try {
  // Find JSON block in stdout (after any print statements)
  const jsonMatch = stdout.match(/\{[\s\S]*\}/);
  result = JSON.parse(jsonMatch ? jsonMatch[0] : stdout);
} catch (e) {
  throw new Error('Could not parse image generation output: ' + stdout);
}

if (result.status !== 'success') {
  throw new Error('Image generation returned error: ' + JSON.stringify(result));
}

return [{ json: result }];
